     3→import { google } from 'googleapis';
     4→import { createServer } from 'http';
     5→import { parse } from 'url';
     6→import open from 'open';
     7→import { readFileSync, existsSync } from 'fs';
     8→import { fileURLToPath } from 'url';
     9→import { dirname, join } from 'path';
    10→import minimist from 'minimist';
    11→import readline from 'readline';
    12→import { saveTokens, listAccounts, setDefaultAccount } from './auth-utils.js';
    13→
    14→const __filename = fileURLToPath(import.meta.url);
    15→const __dirname = dirname(__filename);
    16→
    17→const CREDENTIALS_PATH = join(__dirname, 'credentials.json');
    18→const SCOPES = [
    19→  'https://www.googleapis.com/auth/gmail.modify',
    20→  'https://www.googleapis.com/auth/gmail.settings.basic'
    21→];
    22→
    23→function promptEmail() {
    24→  return new Promise((resolve) => {
    25→    const rl = readline.createInterface({
    26→      input: process.stdin,
    27→      output: process.stdout
    28→    });
    29→
    30→    rl.question('📧 Enter the email address for this account: ', (email) => {
    31→      rl.close();
    32→      resolve(email.trim());
    33→    });
    34→  });
    35→}
    36→
    37→async function setupOAuth(accountId, userEmail = null) {
    38→  console.log('\n🔐 Gmail OAuth Setup\n');
    39→
    40→  if (accountId) {
    41→    console.log(`Setting up account: ${accountId}\n`);
    42→  }
    43→
    44→  // Check if credentials.json exists
    45→  if (!existsSync(CREDENTIALS_PATH)) {
    46→    console.error('❌ Error: credentials.json not found!');
    47→    console.log('\nPlease follow these steps:');
    48→    console.log('1. Go to: https://console.cloud.google.com/');
    49→    console.log('2. Create a new project or select existing one');
    50→    console.log('3. Enable Gmail API');
    51→    console.log('4. Create OAuth 2.0 credentials (Desktop app)');
    52→    console.log('5. Download credentials.json');
    53→    console.log(`6. Save it to: ${CREDENTIALS_PATH}\n`);
    54→    console.log('📖 See docs/google-cloud-setup.md for detailed instructions\n');
    55→    process.exit(1);
    56→  }
    57→
    58→  // Load credentials
    59→  const credentials = JSON.parse(readFileSync(CREDENTIALS_PATH, 'utf8'));
    60→  const { client_id, client_secret, redirect_uris } = credentials.installed || credentials.web;
    61→
    62→  const oauth2Client = new google.auth.OAuth2(
    63→    client_id,
    64→    client_secret,
    65→    'http://localhost:3000/oauth2callback'
    66→  );
    67→
    68→  // Generate auth URL
    69→  const authUrl = oauth2Client.generateAuthUrl({
    70→    access_type: 'offline',
    71→    scope: SCOPES,
    72→    prompt: 'consent' // Force consent screen to ensure we get refresh token
    73→  });
    74→
    75→  console.log('🌐 Opening browser for authorization...');
    76→  console.log('If browser doesn\'t open, visit this URL:\n');
    77→  console.log(authUrl + '\n');
    78→
    79→  // Prompt for email if not provided
    80→  const email = userEmail || await promptEmail();
    81→
    82→  // Start local server to receive callback
    83→  const server = createServer(async (req, res) => {
    84→    if (req.url.indexOf('/oauth2callback') > -1) {
    85→      const qs = parse(req.url, true).query;
    86→      const code = qs.code;
    87→
    88→      res.writeHead(200, { 'Content-Type': 'text/html' });
    89→      res.end('✅ Authorization successful! You can close this window and return to the terminal.');
    90→
    91→      server.close();
    92→
    93→      // Exchange code for tokens
    94→      try {
    95→        const { tokens } = await oauth2Client.getToken(code);
    96→
    97→        // Save tokens with account ID
    98→        const targetAccountId = accountId || 'default';
    99→        saveTokens(targetAccountId, tokens, email);
   100→
   101→        // List all accounts
   102→        const accounts = listAccounts();
   103→        const isFirstAccount = accounts.length === 1;
   104→
   105→        console.log('\n✅ Success! Tokens saved for account:', targetAccountId);
   106→        console.log(`📧 Email: ${email}`);
   107→
   108→        if (isFirstAccount) {
   109→          console.log('⭐ Set as default account');
   110→        }
   111→
   112→        console.log('\n📋 All configured accounts:');
   113→        accounts.forEach(acc => {
   114→          const marker = acc.isDefault ? '⭐' : '  ';
   115→          console.log(`${marker} ${acc.id} (${acc.email})`);
   116→        });
   117→
   118→        console.log('\n🚀 You can now use the Gmail skill!\n');
   119→        console.log('💡 Next steps:');
   120→        console.log('   - Add another account: npm run setup -- --account <account-id>');
   121→        console.log('   - List accounts: node scripts/manage-accounts.js --list');
   122→        console.log('   - Set default: node scripts/manage-accounts.js --set-default <account-id>\n');
   123→      } catch (error) {
   124→        console.error('\n❌ Error exchanging code for tokens:', error.message);
   125→        process.exit(1);
   126→      }
   127→    }
   128→  }).listen(3000, () => {
   129→    open(authUrl);
   130→  });
   131→}
   132→
   133→// Parse command line arguments
   134→const args = minimist(process.argv.slice(2));
   135→const accountId = args.account || null;
   136→const email = args.email || null;
   137→
   138→setupOAuth(accountId, email).catch(console.error);
   139→

