     1→#!/usr/bin/env node
     2→
     3→import { google } from 'googleapis';
     4→import minimist from 'minimist';
     5→import { getAuthClient, parseAccountArg } from './auth/auth-utils.js';
     6→import { logAction } from './action-logger.js';
     7→
     8→function decodeBody(body) {
     9→  if (!body.data) return '';
    10→  return Buffer.from(body.data, 'base64').toString('utf-8');
    11→}
    12→
    13→function extractBody(payload) {
    14→  if (payload.body && payload.body.data) {
    15→    return decodeBody(payload.body);
    16→  }
    17→
    18→  if (payload.parts) {
    19→    // Try to find text/plain first, fall back to text/html
    20→    const textPart = payload.parts.find(part => part.mimeType === 'text/plain');
    21→    if (textPart && textPart.body.data) {
    22→      return decodeBody(textPart.body);
    23→    }
    24→
    25→    const htmlPart = payload.parts.find(part => part.mimeType === 'text/html');
    26→    if (htmlPart && htmlPart.body.data) {
    27→      return decodeBody(htmlPart.body);
    28→    }
    29→
    30→    // Recursively search nested parts
    31→    for (const part of payload.parts) {
    32→      if (part.parts) {
    33→        const body = extractBody(part);
    34→        if (body) return body;
    35→      }
    36→    }
    37→  }
    38→
    39→  return '';
    40→}
    41→
    42→async function readMessage(args) {
    43→  if (!args.id) {
    44→    throw new Error('Missing required argument: --id (message ID)');
    45→  }
    46→
    47→  // Get authenticated client for specified account (or default)
    48→  const accountId = parseAccountArg(args);
    49→  const oauth2Client = await getAuthClient(accountId);
    50→
    51→  const gmail = google.gmail({ version: 'v1', auth: oauth2Client });
    52→
    53→  // Get message details
    54→  const message = await gmail.users.messages.get({
    55→    userId: 'me',
    56→    id: args.id,
    57→    format: 'full'
    58→  });
    59→
    60→  const headers = message.data.payload.headers;
    61→  const getHeader = (name) => headers.find(h => h.name === name)?.value || '';
    62→
    63→  const result = {
    64→    success: true,
    65→    id: message.data.id,
    66→    threadId: message.data.threadId,
    67→    from: getHeader('From'),
    68→    to: getHeader('To'),
    69→    cc: getHeader('Cc'),
    70→    bcc: getHeader('Bcc'),
    71→    subject: getHeader('Subject'),
    72→    date: getHeader('Date'),
    73→    labels: message.data.labelIds || [],
    74→    snippet: message.data.snippet,
    75→    body: extractBody(message.data.payload),
    76→    account: accountId || 'default'
    77→  };
    78→
    79→  // Optionally get thread if requested
    80→  if (args.thread) {
    81→    const thread = await gmail.users.threads.get({
    82→      userId: 'me',
    83→      id: message.data.threadId
    84→    });
    85→
    86→    result.thread = {
    87→      id: thread.data.id,
    88→      messageCount: thread.data.messages.length,
    89→      messages: thread.data.messages.map(msg => ({
    90→        id: msg.id,
    91→        snippet: msg.snippet,
    92→        from: msg.payload.headers.find(h => h.name === 'From')?.value,
    93→        date: msg.payload.headers.find(h => h.name === 'Date')?.value
    94→      }))
    95→    };
    96→  }
    97→
    98→  return result;
    99→}
   100→
   101→// Main execution
   102→const args = minimist(process.argv.slice(2));
   103→const startTime = Date.now();
   104→
   105→readMessage(args)
   106→  .then(result => {
   107→    // Log the action
   108→    logAction('read', args, result, {
   109→      account: result.account,
   110→      duration: Date.now() - startTime
   111→    });
   112→
   113→    console.log(JSON.stringify(result, null, 2));
   114→  })
   115→  .catch(error => {
   116→    const errorResult = {
   117→      success: false,
   118→      error: error.message
   119→    };
   120→
   121→    // Log the failed action
   122→    logAction('read', args, errorResult, {
   123→      account: args.account || 'default',
   124→      duration: Date.now() - startTime,
   125→      failed: true
   126→    });
