     3→import { google } from 'googleapis';
     4→import minimist from 'minimist';
     5→import { getAuthClient, parseAccountArg } from './auth/auth-utils.js';
     6→import { logAction } from './action-logger.js';
     7→
     8→async function searchEmails(args) {
     9→  // Default to showing 10 results
    10→  const maxResults = args.limit || args.max || 10;
    11→  const query = args.query || args.q || '';
    12→
    13→  // Get authenticated client for specified account (or default)
    14→  const accountId = parseAccountArg(args);
    15→  const oauth2Client = await getAuthClient(accountId);
    16→
    17→  const gmail = google.gmail({ version: 'v1', auth: oauth2Client });
    18→
    19→  // Search messages
    20→  const searchResult = await gmail.users.messages.list({
    21→    userId: 'me',
    22→    q: query,
    23→    maxResults: maxResults
    24→  });
    25→
    26→  if (!searchResult.data.messages) {
    27→    return {
    28→      success: true,
    29→      count: 0,
    30→      messages: [],
    31→      query: query
    32→    };
    33→  }
    34→
    35→  // Get full details for each message
    36→  const messages = await Promise.all(
    37→    searchResult.data.messages.map(async (msg) => {
    38→      const details = await gmail.users.messages.get({
    39→        userId: 'me',
    40→        id: msg.id,
    41→        format: 'metadata',
    42→        metadataHeaders: ['From', 'To', 'Subject', 'Date']
    43→      });
    44→
    45→      const headers = details.data.payload.headers;
    46→      const getHeader = (name) => headers.find(h => h.name === name)?.value || '';
    47→
    48→      return {
    49→        id: msg.id,
    50→        threadId: msg.threadId,
    51→        from: getHeader('From'),
    52→        to: getHeader('To'),
    53→        subject: getHeader('Subject'),
    54→        date: getHeader('Date'),
    55→        snippet: details.data.snippet,
    56→        labels: details.data.labelIds || []
    57→      };
    58→    })
    59→  );
    60→
    61→  return {
    62→    success: true,
    63→    count: messages.length,
    64→    total: searchResult.data.resultSizeEstimate,
    65→    query: query,
    66→    messages: messages,
    67→    account: accountId || 'default'
    68→  };
    69→}
    70→
    71→// Main execution
    72→const args = minimist(process.argv.slice(2));
    73→const startTime = Date.now();
    74→
    75→searchEmails(args)
    76→  .then(result => {
    77→    // Log the action
    78→    logAction('search', args, result, {
    79→      account: result.account,
    80→      duration: Date.now() - startTime
    81→    });
    82→
    83→    console.log(JSON.stringify(result, null, 2));
    84→  })
    85→  .catch(error => {
    86→    const errorResult = {
    87→      success: false,
    88→      error: error.message
    89→    };
    90→
    91→    // Log the failed action
    92→    logAction('search', args, errorResult, {
    93→      account: args.account || 'default',
    94→      duration: Date.now() - startTime,
    95→      failed: true
    96→    });
    97→
    98→    console.error(JSON.stringify(errorResult, null, 2));
    99→    process.exit(1);
   100→  });
