    36→  copyFileSync(TOKEN_PATH, BACKUP_PATH);
    37→
    38→  // Migrate to new format
    39→  const migratedConfig = {
    40→    defaultAccount: 'default',
    41→    accounts: {
    42→      default: {
    43→        ...data,
    44→        email: data.email || 'unknown@gmail.com'
    45→      }
    46→    }
    47→  };
    48→
    49→  // Save migrated config
    50→  writeFileSync(TOKEN_PATH, JSON.stringify(migratedConfig, null, 2), { mode: 0o600 });
