    10→// Log file is in the skill root directory, not in scripts/
    11→const SKILL_ROOT = join(__dirname, '..');
    12→const LOG_FILE = join(SKILL_ROOT, 'action-log.jsonl');
    13→
    14→/**
    15→ * Ensure the log file directory exists
    16→ */
    17→function ensureLogDirectory() {
    18→  const logDir = dirname(LOG_FILE);
    19→  if (!existsSync(logDir)) {
    20→    mkdirSync(logDir, { recursive: true });
    21→  }
    22→}
    23→
    24→/**
    25→ * Log an action to the log file
    26→ * @param {string} action - The action type (e.g., 'search', 'send', 'label')
    27→ * @param {Object} params - The parameters used for the action
    28→ * @param {Object} result - The result of the action
    29→ * @param {Object} metadata - Additional metadata (e.g., account, duration)
    30→ */
    31→export function logAction(action, params, result, metadata = {}) {
    32→  ensureLogDirectory();
    33→
    34→  const logEntry = {
    35→    timestamp: new Date().toISOString(),
    36→    action,
    37→    params: sanitizeParams(params),
    38→    result: sanitizeResult(result),
    39→    metadata: {
    40→      ...metadata,
    41→      skill: 'gmail'
    42→    }
    43→  };
    44→
    45→  try {
    46→    // Append as JSON Lines format (one JSON object per line)
    47→    appendFileSync(LOG_FILE, JSON.stringify(logEntry) + '\n', 'utf8');
    48→  } catch (error) {
    49→    // Don't fail the main action if logging fails
    50→    console.error('Warning: Failed to write to action log:', error.message);
    51→  }
    52→}
    53→
    54→/**
    55→ * Sanitize parameters to remove sensitive data and limit size
    56→ */
    57→function sanitizeParams(params) {
    58→  const sanitized = { ...params };
    59→
    60→  // Remove sensitive fields
    61→  const sensitiveFields = ['password', 'token', 'access_token', 'refresh_token'];
    62→  sensitiveFields.forEach(field => {
    63→    if (sanitized[field]) {
    64→      sanitized[field] = '[REDACTED]';
    65→    }
    66→  });
    67→
    68→  // Truncate very long string values
    69→  Object.keys(sanitized).forEach(key => {
    70→    if (typeof sanitized[key] === 'string' && sanitized[key].length > 1000) {
    71→      sanitized[key] = sanitized[key].substring(0, 1000) + '... [truncated]';
    72→    }
    73→  });
    74→
    75→  return sanitized;
    76→}
    77→
    78→/**
    79→ * Sanitize result to limit size while keeping useful information
    80→ */
    81→function sanitizeResult(result) {
    82→  const sanitized = { ...result };
    83→
    84→  // Keep success status and counts
    85→  if (sanitized.success !== undefined) {
    86→    // Success is important
    87→  }
    88→
    89→  if (sanitized.count !== undefined || sanitized.total !== undefined) {
    90→    // Counts are useful
    91→  }
    92→
    93→  // For message/email results, keep summary info but limit details
    94→  if (sanitized.messages && Array.isArray(sanitized.messages)) {
    95→    sanitized.messageCount = sanitized.messages.length;
    96→    // Keep only essential fields from first few messages
    97→    sanitized.messageSummary = sanitized.messages.slice(0, 3).map(msg => ({
    98→      id: msg.id,
    99→      threadId: msg.threadId,
   100→      from: msg.from,
   101→      subject: msg.subject,
   102→      date: msg.date,
   103→      labels: msg.labels
   104→    }));
   105→    delete sanitized.messages;
   106→  }
   107→
   108→  // For label results
   109→  if (sanitized.labels && Array.isArray(sanitized.labels)) {
   110→    sanitized.labelCount = sanitized.labels.length;
   111→    sanitized.labelNames = sanitized.labels.map(l => l.name || l.id).slice(0, 10);
   112→    delete sanitized.labels;
   113→  }
   114→
   115→  // Truncate error messages
   116→  if (sanitized.error && sanitized.error.length > 500) {
   117→    sanitized.error = sanitized.error.substring(0, 500) + '... [truncated]';
   118→  }
   119→
   120→  return sanitized;
   121→}
   122→
   123→/**
   124→ * Get the log file path (useful for scripts that want to reference it)
   125→ */
   126→export function getLogFilePath() {
   127→  return LOG_FILE;
   128→}
