## Email Operations Code

### 4. **Sending Emails** (`gmail-send.js`)

```javascript
function createEmailMessage(to, subject, body, options = {}) {
  const { cc, bcc, html, replyTo } = options;

  const headers = [
    `To: ${to}`,
    `Subject: ${subject}`,
  ];

  if (cc) headers.push(`Cc: ${cc}`);
  if (bcc) headers.push(`Bcc: ${bcc}`);
  if (replyTo) headers.push(`Reply-To: ${replyTo}`);

  headers.push('Content-Type: text/html; charset=utf-8');
  headers.push('');

  const message = headers.join('\r\n') + (html || body);

  return Buffer.from(message)
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

async function sendEmail(args) {
  // Get authenticated client
  const accountId = parseAccountArg(args);
  const oauth2Client = await getAuthClient(accountId);

  const gmail = google.gmail({ version: 'v1', auth: oauth2Client });

  // Create and send email
  const encodedMessage = createEmailMessage(args.to, args.subject, args.body, {
    cc: args.cc,
    bcc: args.bcc,
    html: args.html,
    replyTo: args['reply-to']
  });

  const result = await gmail.users.messages.send({
    userId: 'me',
    requestBody: {
      raw: encodedMessage
    }
  });

  return {
    success: true,
    messageId: result.data.id,
    threadId: result.data.threadId,
    to: args.to,
    subject: args.subject,
    account: accountId || 'default'
  };
}
```

### 5. **Reading Messages** (`gmail-read.js`)

```javascript
function decodeBody(body) {
  if (!body.data) return '';
  return Buffer.from(body.data, 'base64').toString('utf-8');
}

function extractBody(payload) {
  if (payload.body && payload.body.data) {
    return decodeBody(payload.body);
  }

  if (payload.parts) {
    // Try to find text/plain first, fall back to text/html
    const textPart = payload.parts.find(part => part.mimeType === 'text/plain');
    if (textPart && textPart.body.data) {
      return decodeBody(textPart.body);
    }

    const htmlPart = payload.parts.find(part => part.mimeType === 'text/html');
    if (htmlPart && htmlPart.body.data) {
      return decodeBody(htmlPart.body);
    }

    // Recursively search nested parts
    for (const part of payload.parts) {
      if (part.parts) {
        const body = extractBody(part);
        if (body) return body;
      }
    }
  }

  return '';
}

async function readMessage(args) {
  const accountId = parseAccountArg(args);
  const oauth2Client = await getAuthClient(accountId);

  const gmail = google.gmail({ version: 'v1', auth: oauth2Client });

  // Get message details with full format
  const message = await gmail.users.messages.get({
    userId: 'me',
    id: args.id,
    format: 'full'
  });

  const headers = message.data.payload.headers;
  const getHeader = (name) => headers.find(h => h.name === name)?.value || '';

  return {
    success: true,
    id: message.data.id,
    threadId: message.data.threadId,
    from: getHeader('From'),
    to: getHeader('To'),
    cc: getHeader('Cc'),
    bcc: getHeader('Bcc'),
    subject: getHeader('Subject'),
    date: getHeader('Date'),
    labels: message.data.labelIds || [],
    snippet: message.data.snippet,
    body: extractBody(message.data.payload),
    account: accountId || 'default'
  };
}
```

### 6. **Searching Emails** (`gmail-search.js`)

```javascript
async function searchEmails(args) {
  const maxResults = args.limit || args.max || 10;
  const query = args.query || args.q || '';

  const accountId = parseAccountArg(args);
  const oauth2Client = await getAuthClient(accountId);

  const gmail = google.gmail({ version: 'v1', auth: oauth2Client });

  // Search messages using Gmail query syntax
  const searchResult = await gmail.users.messages.list({
    userId: 'me',
    q: query,
    maxResults: maxResults
  });

  if (!searchResult.data.messages) {
    return {
      success: true,
      count: 0,
      messages: [],
      query: query
    };
  }

  // Get full details for each message
  const messages = await Promise.all(
    searchResult.data.messages.map(async (msg) => {
      const details = await gmail.users.messages.get({
        userId: 'me',
        id: msg.id,
        format: 'metadata',
        metadataHeaders: ['From', 'To', 'Subject', 'Date']
      });

      const headers = details.data.payload.headers;
      const getHeader = (name) => headers.find(h => h.name === name)?.value || '';

      return {
        id: msg.id,
        threadId: msg.threadId,
        from: getHeader('From'),
        to: getHeader('To'),
        subject: getHeader('Subject'),
        date: getHeader('Date'),
        snippet: details.data.snippet,
        labels: details.data.labelIds || []
      };
    })
  );

  return {
    success: true,
    count: messages.length,
    total: searchResult.data.resultSizeEstimate,
    query: query,
    messages: messages,
    account: accountId || 'default'
  };
}
```

